// Only1joezzy Delivery — ONE server file: sign-in gate, login page, API and WhatsApp preview image.
// Runs on Vercel before every request. Open routes: /login, /api/login, /api/logout, /preview.jpg.
const CID = "869781144266-gpssv30klfiicbg7r4bnr5n36rv2togb.apps.googleusercontent.com";
const ADMINS = ["itofficialjoseph@gmail.com", "gabtechx@gmail.com"];
const ITEMS = "store:items";
const MONTH = 30 * 86400000;
const enc = new TextEncoder(), dec = new TextDecoder();
const toHex = u8 => Array.from(u8, b => b.toString(16).padStart(2, "0")).join("");
const fromHex = h => Uint8Array.from(h.match(/../g), x => parseInt(x, 16));
const LOGO = "data:image/jpeg;base64,";
const PREVIEW = "";

const LOGIN_PAGE = `<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Sign in · Only1joezzy Delivery</title>
<meta name="robots" content="noindex">
<link href="https://fonts.googleapis.com/css2?family=Outfit:wght@400;600;700&family=DM+Serif+Display&display=swap" rel="stylesheet">
<style>
*{box-sizing:border-box}
body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;background:radial-gradient(circle at 20% 10%,#1a8a66,#06241a 70%);font-family:Outfit,system-ui,sans-serif;color:#fff;overflow:hidden}
.card{width:min(92vw,380px);background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.14);border-radius:26px;padding:30px 24px;text-align:center;backdrop-filter:blur(6px);animation:up .8s both;position:relative;z-index:1}
@keyframes up{from{opacity:0;transform:translateY(30px) scale(.98)}}
.logo{width:min(64vw,230px);background:#fff;border-radius:22px;padding:10px;animation:zi 1s both}
@keyframes zi{from{transform:scale(.6);opacity:0}}
h1{font-family:"DM Serif Display",Georgia,serif;font-weight:400;font-size:28px;margin:16px 0 6px}
p{color:#cfe6dc;font-size:14px;line-height:1.6;margin:0 0 18px}
#gb{display:flex;justify-content:center;min-height:44px}
#msg{min-height:20px;font-size:13px;color:#f0c14b;margin-top:14px}
.fl{position:absolute;font-size:26px;opacity:.3;animation:fy 7s ease-in-out infinite;pointer-events:none}
@keyframes fy{50%{transform:translateY(-22px) rotate(12deg)}}
small{display:block;margin-top:18px;color:#9bb3a8;font-size:12px}
@media(prefers-reduced-motion:reduce){*{animation:none!important}}
</style></head><body>
<span class="fl" style="left:8%;top:14%">🎁</span><span class="fl" style="right:10%;top:22%;animation-delay:2s">🎀</span><span class="fl" style="left:14%;bottom:12%;animation-delay:4s">✨</span><span class="fl" style="right:12%;bottom:18%;animation-delay:1s">💝</span>
<div class="card">
<img class="logo" alt="Only1joezzy Delivery" src="${LOGO}">
<h1>Welcome</h1>
<p>Sign in with your Google account to browse our gifts and place your order.</p>
<div id="gb"></div>
<div id="msg"></div>
<small>We use your Google name and photo only to show your account in the store.</small>
</div>
<script src="https://accounts.google.com/gsi/client" async defer></script>
<script>
const CID="${CID}";
window.onload=()=>{
  google.accounts.id.initialize({client_id:CID,callback:onCred});
  google.accounts.id.renderButton(document.getElementById("gb"),{theme:"filled_blue",size:"large",shape:"pill",text:"continue_with",width:280});
};
async function onCred(r){
  const m=document.getElementById("msg");m.textContent="Signing you in…";
  try{
    const res=await fetch("/api/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({credential:r.credential})});
    if(res.ok){location.replace("/");return}
    m.textContent="Sign-in could not be verified. Please try again.";
  }catch(e){m.textContent="Network error. Please try again."}
}
</script></body></html>`;

const json = (obj, status = 200, extra = {}) =>
  new Response(JSON.stringify(obj), { status, headers: { "Content-Type": "application/json", "Cache-Control": "no-store", ...extra } });

async function hmacHex(text) {
  const key = await crypto.subtle.importKey("raw", enc.encode(process.env.SESSION_SECRET || ""), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return toHex(new Uint8Array(await crypto.subtle.sign("HMAC", key, enc.encode(text))));
}
async function sign(data) {
  const ph = toHex(enc.encode(JSON.stringify(data)));
  return ph + "." + (await hmacHex(ph));
}
async function verify(tok) {
  if (!tok || !process.env.SESSION_SECRET) return null;
  const [ph, sig] = tok.split(".");
  if (!ph || !sig) return null;
  const exp = await hmacHex(ph);
  if (exp.length !== sig.length) return null;
  let diff = 0;
  for (let i = 0; i < exp.length; i++) diff |= exp.charCodeAt(i) ^ sig.charCodeAt(i);
  if (diff !== 0) return null;
  let d;
  try { d = JSON.parse(dec.decode(fromHex(ph))); } catch (e) { return null; }
  return d.x && d.x > Date.now() ? d : null;
}
async function session(request) {
  const m = (request.headers.get("cookie") || "").match(/(?:^|;\s*)o1s=([^;]+)/);
  return m ? verify(m[1]) : null;
}
const isAdmin = d => !!d && ADMINS.includes(String(d.e || "").toLowerCase());

async function googleProfile(credential) {
  const r = await fetch("https://oauth2.googleapis.com/tokeninfo?id_token=" + encodeURIComponent(credential));
  if (!r.ok) return null;
  const j = await r.json();
  if (j.aud !== CID || String(j.email_verified) !== "true") return null;
  return { e: String(j.email).toLowerCase(), n: j.name || "", p: j.picture || "" };
}

async function kv(cmd) {
  const r = await fetch(process.env.KV_REST_API_URL, {
    method: "POST",
    headers: { Authorization: "Bearer " + process.env.KV_REST_API_TOKEN, "Content-Type": "application/json" },
    body: JSON.stringify(cmd),
  });
  const j = await r.json();
  if (j.error) throw new Error(j.error);
  return j.result;
}
async function getItems() {
  const v = await kv(["GET", ITEMS]);
  try { return v ? JSON.parse(v) : []; } catch (e) { return []; }
}

async function api(request, path, d) {
  const url = new URL(request.url);
  if (path === "/api/login" && request.method === "POST") {
    const body = await request.json().catch(() => ({}));
    if (!body.credential) return json({ error: "Missing credential" }, 400);
    const p = await googleProfile(body.credential);
    if (!p) return json({ error: "Sign-in could not be verified" }, 401);
    const tok = await sign({ e: p.e, n: p.n, p: p.p, x: Date.now() + MONTH });
    return json({ ok: true }, 200, { "Set-Cookie": `o1s=${tok}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=2592000` });
  }
  if (path === "/api/logout") {
    return new Response(null, { status: 302, headers: { Location: "/login", "Set-Cookie": "o1s=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0" } });
  }
  if (!d) return json({ error: "Sign in required" }, 401);

  if (path === "/api/me") {
    return json({ email: d.e, name: d.n, picture: d.p, admin: isAdmin(d) });
  }

  if (path === "/api/items") {
    if (request.method === "GET") return json(await getItems());
    if (!isAdmin(d)) return json({ error: "Not authorised" }, 401);
    if (request.method === "POST") {
      const b = await request.json().catch(() => ({}));
      const n = String(b.n || "").trim().slice(0, 120);
      const p = Math.round(Number(b.p));
      const c = String(b.c || "Gifts").slice(0, 30);
      if (!n || !(p > 0)) return json({ error: "Name and price are required" }, 400);
      const img = typeof b.img === "string" && b.img.startsWith("data:image/") && b.img.length < 400000 ? b.img : "";
      const item = {
        id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
        n, p, c, d: String(b.d || "").trim().slice(0, 300), img, by: d.e, at: new Date().toISOString(),
      };
      const list = await getItems();
      list.push(item);
      await kv(["SET", ITEMS, JSON.stringify(list)]);
      return json(item);
    }
    if (request.method === "DELETE") {
      const id = url.searchParams.get("id") || "";
      if (!id) return json({ error: "Missing id" }, 400);
      await kv(["SET", ITEMS, JSON.stringify((await getItems()).filter(x => x.id !== id))]);
      return json({ ok: true });
    }
    return json({ error: "Method not allowed" }, 405);
  }

  if (path === "/api/track" && request.method === "POST") {
    const b = await request.json().catch(() => ({}));
    const ev = ["view", "cart", "order"].includes(b.ev) ? b.ev : null;
    const n = String(b.n || "").trim().slice(0, 120);
    if (!ev || !n) return json({ error: "Bad event" }, 400);
    await kv(["LPUSH", "store:log", JSON.stringify({ e: d.e, ev, n, t: Date.now() })]);
    await kv(["LTRIM", "store:log", "0", "1999"]);
    await kv(["HINCRBY", "store:stats", ev + "|" + n, "1"]);
    return json({ ok: true });
  }

  if (path === "/api/stats" && request.method === "GET") {
    if (!isAdmin(d)) return json({ error: "Not authorised" }, 401);
    const flat = (await kv(["HGETALL", "store:stats"])) || [];
    const map = {};
    for (let i = 0; i < flat.length; i += 2) {
      const k = flat[i], idx = k.indexOf("|");
      const ev = k.slice(0, idx), name = k.slice(idx + 1);
      (map[name] = map[name] || { name, view: 0, cart: 0, order: 0 })[ev] = +flat[i + 1];
    }
    const items = Object.values(map).sort((a, b) => (b.view + b.cart + b.order) - (a.view + a.cart + a.order));
    const logs = [];
    ((await kv(["LRANGE", "store:log", "0", "1999"])) || []).forEach(s => { try { logs.push(JSON.parse(s)); } catch (e) {} });
    const cus = {};
    logs.forEach(x => {
      const c = (cus[x.e] = cus[x.e] || { e: x.e, n: 0, last: 0 });
      c.n++; if (x.t > c.last) c.last = x.t;
    });
    const customers = Object.values(cus).sort((a, b) => b.last - a.last).slice(0, 100);
    return json({ items, recent: logs.slice(0, 40), customers });
  }

  return json({ error: "Not found" }, 404);
}

export default async function middleware(request) {
  const path = new URL(request.url).pathname;

  if (path === "/login" || path === "/login.html") {
    return new Response(LOGIN_PAGE, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
  }
  if (path === "/preview.jpg") {
    return new Response(Uint8Array.from(atob(PREVIEW), c => c.charCodeAt(0)), { headers: { "Content-Type": "image/jpeg", "Cache-Control": "public, max-age=86400" } });
  }
  if (path.startsWith("/api/")) {
    try {
      if (path === "/api/login" || path === "/api/logout") return await api(request, path, null);
      return await api(request, path, await session(request)) ?? undefined;
    } catch (e) {
      return json({ error: "Server error" }, 500);
    }
  }

  // Everything else (the store page): only with a valid session. Otherwise send to sign-in.
  if (await session(request)) return; // undefined = serve index.html
  return Response.redirect(new URL("/login", request.url), 302);
}
